export default "'use strict';\n\nconst {\n  Date,\n  Symbol,\n} = primordials;\n\nconst { setUnrefTimeout } = require('internal/timers');\nconst { getCategoryEnabledBuffer, trace } = internalBinding('trace_events');\nconst {\n  CHAR_LOWERCASE_B,\n  CHAR_LOWERCASE_E,\n} = require('internal/constants');\n\nlet utcCache;\n\nfunction utcDate() {\n  if (!utcCache) cache();\n  return utcCache;\n}\n\nfunction cache() {\n  const d = new Date();\n  utcCache = d.toUTCString();\n  setUnrefTimeout(resetCache, 1000 - d.getMilliseconds());\n}\n\nfunction resetCache() {\n  utcCache = undefined;\n}\n\nlet traceEventId = 0;\n\nfunction getNextTraceEventId() {\n  return ++traceEventId;\n}\n\nconst httpEnabled = getCategoryEnabledBuffer('node.http');\n\nfunction isTraceHTTPEnabled() {\n  return httpEnabled[0] > 0;\n}\n\nconst traceEventCategory = 'node,node.http';\n\nfunction traceBegin(...args) {\n  trace(CHAR_LOWERCASE_B, traceEventCategory, ...args);\n}\n\nfunction traceEnd(...args) {\n  trace(CHAR_LOWERCASE_E, traceEventCategory, ...args);\n}\n\nmodule.exports = {\n  kOutHeaders: Symbol('kOutHeaders'),\n  kNeedDrain: Symbol('kNeedDrain'),\n  utcDate,\n  traceBegin,\n  traceEnd,\n  getNextTraceEventId,\n  isTraceHTTPEnabled,\n};\n"